package com.example.starter.dto;

import java.time.Instant;

/**
 * 调光操作结果（同时作为幂等登记表中的首次结果快照）。
 *
 * @param requestId 幂等键
 * @param circuitId 回路主键
 * @param source    触发来源
 * @param fromLevel 调光前档位，未触发为 null
 * @param toLevel   调光后档位，未触发为 null
 * @param status    结果状态：EXECUTED 已执行 / NOT_TRIGGERED 未触发
 * @param message   结果说明
 * @param createdAt 结果生成时间(UTC)
 * @param replayed  是否幂等重放（同键同参命中首次结果）
 */
public record DimResult(
        String requestId,
        long circuitId,
        String source,
        Integer fromLevel,
        Integer toLevel,
        String status,
        String message,
        Instant createdAt,
        boolean replayed) {

    /** 已执行。 */
    public static final String STATUS_EXECUTED = "EXECUTED";
    /** 未触发（条件不满足或目标档位与当前一致）。 */
    public static final String STATUS_NOT_TRIGGERED = "NOT_TRIGGERED";

    public DimResult withReplayed(boolean value) {
        return new DimResult(requestId, circuitId, source, fromLevel, toLevel, status, message, createdAt, value);
    }
}

package com.example.starter.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 人工调光请求。
 *
 * @param requestId   幂等键，由调用方生成，全局唯一
 * @param targetLevel 目标档位，0 为熄灭
 */
public record DimRequest(
        @NotBlank String requestId,
        @NotNull @Min(0) @Max(5) Integer targetLevel) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 洞外亮度检测请求。
 *
 * @param requestId  幂等键
 * @param brightness 洞外亮度合成值，单位 lux；低于回路阈值升一档，恰等不触发
 */
public record BrightnessRequest(
        @NotBlank String requestId,
        @NotNull @Min(0) Integer brightness) {
}

package com.example.starter.dto;

import java.time.Instant;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 车流量合成检测数据上报请求，按 5 分钟滚动更新。
 *
 * @param requestId 幂等键
 * @param flow      车流量，单位 辆/5分钟；恰等为 0 时降至保底亮度
 * @param sampledAt 采样时间(UTC)，为空时取服务端当前时间
 */
public record TrafficRequest(
        @NotBlank String requestId,
        @NotNull @Min(0) Integer flow,
        Instant sampledAt) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 事故锁定请求。
 *
 * @param requestId 幂等键
 * @param operator  告警操作人
 */
public record AccidentLockRequest(
        @NotBlank String requestId,
        @NotBlank String operator) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 事故解除请求，解除须现场确认。
 *
 * @param requestId 幂等键
 * @param confirmBy 现场确认人，必填
 */
public record AccidentUnlockRequest(
        @NotBlank String requestId,
        @NotBlank String confirmBy) {
}

package com.example.starter.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等指纹工具：指纹覆盖 requestId 与全部业务字段，字段按固定顺序以 '|' 拼接后取 SHA-256。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算指纹。第一个字段必须为 requestId，其余为全部业务字段（null 以空串参与）。
     */
    public static String of(String requestId, Object... businessFields) {
        StringBuilder sb = new StringBuilder(requestId == null ? "" : requestId);
        for (Object field : businessFields) {
            sb.append('|').append(field == null ? "" : field.toString());
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

