private DimResult idempotent(String requestId, String fingerprint, Supplier<DimResult> action) {
    var existing = writeRequestRepo.findByRequestId(requestId);
    if (existing.isPresent()) {
        return replay(existing.get(), fingerprint);
    }
    DimResult result = action.get();
    try {
        writeRequestRepo.insert(requestId, fingerprint, toJson(result), clock.instant());
    } catch (DuplicateKeyException e) {
        // 并发同键：以先登记为准
        var winner = writeRequestRepo.findByRequestId(requestId).orElseThrow(() -> e);
        return replay(winner, fingerprint);
    }
    return result;
}

private DimResult replay(WriteRequest wr, String fingerprint) {
    if (!wr.fingerprint().equals(fingerprint)) {
        throw BizException.conflict("IDEMPOTENCY_CONFLICT", "同一 requestId 业务参数不一致");
    }
    return fromJson(wr.resultJson()).withReplayed(true);
}
```

