private DimResult executeIdempotent(long circuitId, String requestId, String fingerprint, Function<Circuit, DimResult> biz) {
    var existing = writeRequestRepo.findByRequestId(requestId);
    if (existing.isPresent()) return replay(existing.get(), fingerprint);
    Circuit c = requireCircuitForUpdate(circuitId);
    var recheck = writeRequestRepo.findByRequestId(requestId);
    if (recheck.isPresent()) return replay(recheck.get(), fingerprint);
    DimResult result = biz.apply(c);
    try {
        writeRequestRepo.insert(requestId, fingerprint, toJson(result), clock.instant());
    } catch (DuplicateKeyException e) {
        return replay(writeRequestRepo.findByRequestId(requestId).orElseThrow(), fingerprint);
    }
    return result;
}
```

