            List<DimRecord> records = recordRepo.findBetween(c.id(), dayStart, dayEnd);
            int startLevel = recordRepo.findLatestBefore(c.id(), dayStart).map(DimRecord::toLevel).orElse(c.initialLevel());
            long wattSeconds = 0;
            Instant segStart = dayStart;
            int level = startLevel;
            for (DimRecord r : records) {
                wattSeconds += watts(level) * Duration.between(segStart, r.createdAt()).getSeconds();
                segStart = r.createdAt();
                level = r.toLevel();
            }
            wattSeconds += watts(level) * Duration.between(segStart, end).getSeconds();
            long energyMwh = wattSeconds * 1000 / 3600;
            settlementRepo.upsert(c.id(), date, records.size(), energyMwh, now);
            out.add(new SettlementView(c.id(), c.code(), c.name(), date, records.size(), energyMwh));
        }
        return out;
    }
}
