    @Test
    void 并发同键同参仅执行一次() throws Exception {
        int threads = 8;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<DimResult>> futures = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            futures.add(pool.submit(() -> {
                ready.countDown();
                start.await(5, TimeUnit.SECONDS);
                return service.dimManually(1L, new DimRequest("r-conc-same", 4));
            }));
        }
        assertTrue(ready.await(10, TimeUnit.SECONDS));
        start.countDown();
        List<DimResult> results = new ArrayList<>();
        for (Future<DimResult> f : futures) results.add(f.get(15, TimeUnit.SECONDS));
        pool.shutdown();
        assertEquals(threads, results.size());
        long executed = results.stream().filter(r -> !r.replayed()).count();
        assertEquals(1, executed);
        assertTrue(results.stream().allMatch(r -> r.toLevel() == 4));
        assertEquals(1, commandRepo.countByRequestId("r-conc-same"));
        assertEquals(1, recordRepo.countByCircuit(1L));
        assertEquals(4, service.getCircuit(1L).currentLevel());
    }
